<?php session_start();require __DIR__.'/../config.php';if(!empty($_SESSION['admin_ok'])){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(hash_equals(ADMIN_USERNAME,$_POST['username']??'')&&ADMIN_PASSWORD_HASH!==''&&password_verify($_POST['password']??'',ADMIN_PASSWORD_HASH)){session_regenerate_id(true);$_SESSION['admin_ok']=true;$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location:index.php');exit;}$error='Invalid username or password.';}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>body{min-height:100vh;background:#101114;color:#eee}.card{background:#181a1f}.form-control,.form-control:focus{background:#111318;color:#fff}</style></head><body class="d-flex align-items-center"><div class="container"><div class="row justify-content-center"><div class="col-sm-10 col-md-6 col-lg-4"><div class="card p-4"><div class="text-center mb-4"><i class="bi bi-shield-lock display-5"></i><h2>Admin Login</h2></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><label class="form-label">Username</label><input name="username" class="form-control mb-3" required><label class="form-label">Password</label><input type="password" name="password" class="form-control mb-4" required><button class="btn btn-primary w-100"><i class="bi bi-box-arrow-in-right"></i> Login</button></form></div></div></div></div></body></html>